import React, { useState, useEffect, useCallback } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

// Palette de couleurs moderne
const COLORS = {
  primary: '#4F46E5',
  primaryLight: '#EEF2FF',
  success: '#10B981',
  successLight: '#DCFCE7',
  danger: '#EF4444',
  dangerLight: '#FEE2E2',
  warning: '#F59E0B',
  warningLight: '#FEF3C7',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const Dashboard = ({ addNotification }) => {
  // ============ STATE ============
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });
  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  // ============ LOGIQUE DE CHARGEMENT ============
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      console.log(' [DASHBOARD] Loading data...');

      // Exécution parallèle des appels API
      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),       // /students/stats/
        attendanceAPI.getStats(),     // /attendance/stats/
        attendanceAPI.getTodayLog(),  // /attendance/
        attendanceAPI.getStatus()     // /attendance/status/
      ]);

      console.log(' [DASHBOARD] All API responses received');
      console.log(' Student Stats:', studentStatsRes);
      console.log(' Attendance Stats:', attendanceStatsRes);
      console.log(' Today Log:', logRes);
      console.log(' Status:', statusRes);

      // 1. Vérifier les réponses
      if (!studentStatsRes.success) {
        console.error(' Student stats failed:', studentStatsRes.error);
        setError(`Erreur stats étudiants: ${studentStatsRes.error}`);
        setLoading(false);
        return;
      }

      if (!attendanceStatsRes.success) {
        console.error(' Attendance stats failed:', attendanceStatsRes.error);
        setError(`Erreur stats présence: ${attendanceStatsRes.error}`);
        setLoading(false);
        return;
      }

      if (!logRes.success) {
        console.error(' Log failed:', logRes.error);
        setError(`Erreur log: ${logRes.error}`);
        setLoading(false);
        return;
      }

      if (!statusRes.success) {
        console.error(' Status failed:', statusRes.error);
        setError(`Erreur statut: ${statusRes.error}`);
        setLoading(false);
        return;
      }

      // 2. Calcul des statistiques globales
      const sData = studentStatsRes.data || {};
      const active = Number(sData.active_students) || 0;

      // Compter les présents d'aujourd'hui
      const logs = logRes.data?.records || [];
      const logStudentIds = new Set(logs.map(r => r.student_id));
      const present = logStudentIds.size;

      console.log(` Calculated: active=${active}, present=${present}`);

      setStats({
        active_students: active,
        present_today: present,
        absent_today: Math.max(0, active - present),
        summary: attendanceStatsRes.data || {}
      });

      // 3. Journal des scans
      setAttendanceLog(logs);
      console.log(` Attendance log: ${logs.length} records`);

      // 4. Liste de présence
      const students = statusRes.data?.students || [];
      setStatusList(students);
      console.log(`👥 Status list: ${students.length} students`);

      setLastUpdated(new Date().toLocaleTimeString());
      setError(null);

    } catch (err) {
      console.error(' [DASHBOARD] Error loading data:', err);
      setError(err.response?.data?.error || err.message || 'Erreur de connexion au serveur');
      if (addNotification) {
        addNotification(' Erreur chargement dashboard', 'error');
      }
    } finally {
      setLoading(false);
    }
  }, [addNotification]);

  // ============ CYCLE DE VIE ============
  useEffect(() => {
    loadData();
    // Rafraîchissement automatique toutes les 20 secondes
    const interval = setInterval(loadData, 20000);
    return () => clearInterval(interval);
  }, [loadData]);

  // ============ RENDU ERREUR ============
  if (error) {
    return (
      <div style={styles.container}>
        <div style={styles.errorCard}>
          <h3 style={styles.errorTitle}>⚠️ Problème de synchronisation</h3>
          <p style={styles.errorText}>{error}</p>
          <p style={styles.debugText}>
            💡 Conseil: Vérifier que tous les étudiants sont enregistrés et que le backend répond correctement.
          </p>
          <button onClick={loadData} style={styles.retryBtn}> Réessayer la connexion</button>
        </div>
      </div>
    );
  }

  if (loading && stats.active_students === 0) {
    return (
      <div style={styles.container}>
        <div style={styles.loadingCard}>
          <p style={styles.loadingText}>⏳ Chargement des données...</p>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Tableau de Bord IA</h2>
          <p style={styles.subtitle}>Statut de présence en temps réel • {lastUpdated || '--:--'}</p>
        </div>
        <button onClick={loadData} style={styles.refreshBtn} disabled={loading}>
          {loading ? '⏳ Chargement...' : '🔄 Actualiser'}
        </button>
      </div>

      {/* CARTES DE STATISTIQUES */}
      <div style={styles.statsGrid}>
        <StatCard 
          icon="👥" 
          label="Inscrits" 
          value={stats.active_students} 
          color={COLORS.primary} 
          bgColor={COLORS.primaryLight} 
        />
        <StatCard 
          icon="✅" 
          label="Présents" 
          value={stats.present_today} 
          color={COLORS.success} 
          bgColor={COLORS.successLight} 
        />
        <StatCard 
          icon="❌" 
          label="Absents" 
          value={stats.absent_today} 
          color={COLORS.danger} 
          bgColor={COLORS.dangerLight} 
        />
        <StatCard 
          icon="📈" 
          label="Taux" 
          value={stats.active_students > 0 ? `${((stats.present_today / stats.active_students) * 100).toFixed(1)}%` : '0%'} 
          color={COLORS.warning} 
          bgColor={COLORS.warningLight}
        />
      </div>

      <div style={styles.mainGrid}>
        {/* COLONNE GAUCHE : LOGS RECENTS */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>📋 Derniers Scans (Aujourd'hui)</h3>
          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}>
              Aucune activité détectée aujourd'hui.
              <p style={styles.emptyStateHint}>💡 Utilisez la caméra pour scanner les étudiants</p>
            </div>
          ) : (
            <div style={styles.table}>
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Étudiant</div>
                <div style={{ flex: 1 }}>Score IA</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>
              {attendanceLog.slice(0, 10).map((record, idx) => (
                <div key={idx} style={styles.tableRow}>
                  <div style={{ flex: 2, fontWeight: 600 }}>
                    {String(record.student || record.name || 'Inconnu')}
                  </div>
                  <div style={{ flex: 1 }}>
                    <ConfidenceBadge confidence={record.confidence} />
                  </div>
                  <div style={{ flex: 1, color: COLORS.textMuted }}>
                    {String(record.timestamp || '--:--')}
                  </div>
                </div>
              ))}
            </div>
          )}
          <p style={styles.tableInfo}>
            Total: {attendanceLog.length} scans aujourd'hui
          </p>
        </div>

        {/* COLONNE DROITE : ANALYSE IA */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>⚙️ Analyse Pipeline</h3>
          <div style={styles.summaryBox}>
            <SummaryItem 
              label="Total Scans" 
              value={stats.summary?.total_records || 0} 
              color={COLORS.primary} 
            />
            <SummaryItem 
              label="Précision Moyenne" 
              value={stats.summary?.avg_confidence ? `${(stats.summary.avg_confidence * 100).toFixed(1)}%` : 'N/A'} 
              color={COLORS.success} 
            />
            <SummaryItem 
              label="Précision Max" 
              value={stats.summary?.max_confidence ? `${(stats.summary.max_confidence * 100).toFixed(1)}%` : 'N/A'} 
              color={COLORS.success} 
            />
            <div style={styles.infoNote}>
              Données calculées sur les scans du jour.
            </div>
          </div>
        </div>
      </div>

      {/* SECTION BASSE : LISTE COMPLETE */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>👥 Liste d'Appel Complète</h3>
        {statusList.length === 0 ? (
          <div style={styles.emptyState}>
            Aucun étudiant inscrit.
            <p style={styles.emptyStateHint}>💡 Utilisez la fonction Enrôlement pour ajouter des étudiants</p>
          </div>
        ) : (
          <div style={styles.table}>
            <div style={styles.tableHeader}>
              <div style={{ flex: 2 }}>Nom de l'étudiant</div>
              <div style={{ flex: 2 }}>Email</div>
              <div style={{ flex: 1 }}>Statut</div>
            </div>
            {statusList.map((student, idx) => (
              <div key={idx} style={styles.tableRow}>
                <div style={{ flex: 2, fontWeight: 500 }}>
                  {String(student.name || 'Inconnu')}
                </div>
                <div style={{ flex: 2, fontSize: '0.85rem', color: COLORS.textMuted }}>
                  {String(student.email || '—')}
                </div>
                <div style={{ flex: 1 }}>
                  <StatusBadge present={student.present} />
                </div>
              </div>
            ))}
          </div>
        )}
        <p style={styles.tableInfo}>
          Total: {statusList.length} étudiants inscrits | {statusList.filter(s => s.present).length} présents
        </p>
      </div>
    </div>
  );
};

// ============ SOUS-COMPOSANTS UI ============

const StatCard = ({ icon, label, value, color, bgColor }) => (
  <div style={{ ...styles.statCard, borderLeft: `5px solid ${color}` }}>
    <div style={{ ...styles.statIconWrapper, backgroundColor: bgColor }}>{icon}</div>
    <div style={styles.statContent}>
      <p style={styles.statLabel}>{label}</p>
      <p style={{ ...styles.statValue, color }}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ confidence }) => {
  const score = confidence || 0;
  const color = score > 0.7 ? '#166534' : score > 0.4 ? '#92400E' : '#991B1B';
  const bg = score > 0.7 ? COLORS.successLight : score > 0.4 ? COLORS.warningLight : COLORS.dangerLight;
  return (
    <span style={{ padding: '4px 8px', backgroundColor: bg, color, borderRadius: '4px', fontSize: '0.75rem', fontWeight: 800 }}>
      {(score * 100).toFixed(0)}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span style={{ 
    padding: '6px 12px', 
    backgroundColor: present ? COLORS.successLight : COLORS.dangerLight, 
    color: present ? '#166534' : '#991B1B', 
    borderRadius: '6px', fontSize: '0.8rem', fontWeight: 700 
  }}>
    {present ? '● PRÉSENT' : '○ ABSENT'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{ ...styles.summaryValue, color }}>{value}</p>
  </div>
);

// ============ STYLES (CSS-in-JS) ============
const styles = {
  container: { padding: '30px', maxWidth: '1200px', margin: '0 auto', backgroundColor: COLORS.background, minHeight: '100vh' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' },
  title: { margin: 0, fontSize: '2rem', fontWeight: 800, color: COLORS.textMain },
  subtitle: { margin: '5px 0 0 0', color: COLORS.textMuted },
  refreshBtn: { padding: '10px 20px', backgroundColor: COLORS.primary, color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 },
