  statIconWrapper: { width: '45px', height: '45px', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem' },
  statLabel: { margin: 0, fontSize: '0.75rem', color: COLORS.textMuted, fontWeight: 700, textTransform: 'uppercase' },
  statValue: { margin: 0, fontSize: '1.6rem', fontWeight: 800 },
  mainGrid: { display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px', marginBottom: '25px' },
  section: { backgroundColor: COLORS.surface, borderRadius: '15px', padding: '20px', boxShadow: '0 2px 10px rgba(0,0,0,0.03)' },
  sectionTitle: { marginTop: 0, marginBottom: '20px', fontSize: '1.1rem', fontWeight: 700 },
  table: { width: '100%' },
  tableHeader: { display: 'flex', padding: '12px', borderBottom: `2px solid ${COLORS.background}`, color: COLORS.textMuted, fontSize: '0.85rem', fontWeight: 700 },
  tableRow: { display: 'flex', padding: '15px 12px', borderBottom: `1px solid ${COLORS.background}`, alignItems: 'center' },
  tableInfo: { margin: '15px 0 0 0', fontSize: '0.8rem', color: COLORS.textMuted, textAlign: 'right' },
  summaryBox: { display: 'flex', flexDirection: 'column', gap: '15px' },
  summaryItem: { padding: '15px', backgroundColor: COLORS.background, borderRadius: '10px' },
  summaryLabel: { margin: 0, fontSize: '0.85rem', color: COLORS.textMuted },
  summaryValue: { margin: '5px 0 0 0', fontSize: '1.4rem', fontWeight: 800 },
  infoNote: { fontSize: '0.8rem', color: COLORS.textMuted, fontStyle: 'italic', marginTop: '10px' },
  emptyState: { padding: '40px', textAlign: 'center', color: COLORS.textMuted },
  emptyStateHint: { margin: '10px 0 0 0', fontSize: '0.85rem', color: COLORS.textMuted },
  errorCard: { padding: '40px', textAlign: 'center', backgroundColor: COLORS.dangerLight, borderRadius: '12px', border: `2px solid ${COLORS.danger}` },
  errorTitle: { color: COLORS.danger, margin: 0 },
  errorText: { color: '#991B1B', marginTop: '10px' },
  debugText: { color: COLORS.textMuted, fontSize: '0.9rem', marginTop: '10px' },
  retryBtn: { padding: '10px 20px', backgroundColor: COLORS.danger, color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginTop: '15px' },
  loadingCard: { padding: '60px', textAlign: 'center', backgroundColor: COLORS.surface, borderRadius: '12px', marginTop: '50px' },
  loadingText: { color: COLORS.textMuted, fontSize: '1.1rem', fontWeight: 500 }
